-- ตารางขั้นต่ำสำหรับทดสอบ hr-position-api ในเครื่อง (ฐานจริงมีอยู่แล้ว — ไม่ใช่ migration)
create table if not exists public.org_departments(id uuid primary key default gen_random_uuid(), organization_id uuid, parent_id uuid, department_code text, name text, status text default 'active', metadata jsonb default '{}', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.hr_positions(id uuid primary key default gen_random_uuid(), position_code text unique, name_th text, name_en text, department text, level text, description text, status text default 'active' check (status in ('active','inactive')), created_by text, updated_by text, created_at timestamptz default now(), updated_at timestamptz default now(), department_id uuid, version int default 1);
create table if not exists public.it_position_permissions(id uuid primary key default gen_random_uuid(), position_id uuid, application_key text, permission_codes text[] default '{}', branch_scope text default 'assigned', status text default 'draft' check (status in ('draft','active','inactive')), version int default 1, updated_by text, updated_at timestamptz default now(), unique(position_id,application_key));
create table if not exists public.hr_position_audit(id uuid primary key default gen_random_uuid(), position_id uuid, action text not null, before_state jsonb, after_state jsonb, actor text not null, created_at timestamptz default now());
create table if not exists public.iam_audit_log(id uuid primary key default gen_random_uuid(), actor_ref text not null, action_key text not null, target_type text not null, target_id text, before_state jsonb, after_state jsonb, policy_version int, created_at timestamptz default now());
create table if not exists public.iam_sync_outbox(id uuid primary key default gen_random_uuid(), event_key text not null, aggregate_type text not null, aggregate_id text not null, aggregate_version int default 1, event_type text not null, schema_version int default 1, payload jsonb not null, status text default 'pending');
alter table public.staff add column if not exists position_id uuid;
create table if not exists public.staff_position_history(id uuid primary key default gen_random_uuid(), staff_id uuid, changed_at timestamptz default now());
insert into public.hr_positions(position_code,name_th) values('BARISTA','บาริสต้า'),('MANAGER','ผู้จัดการร้าน'),('FINAL_VERIFIER','Final Verifier') on conflict do nothing;
